import {S,P,T,D,C,U,refs,motivation} from './model.mjs';
export default [
S('Интерфейсы, объектная модель и проектирование данных','Экраны и данные для согласованного пути заявки',P(['Экраны','Действия Анны и Ирины'],['Объекты','Пользователь, проект и заявка'],['Хранение','Связанные таблицы и ограничения']),
'На втором вебинаре превратим требования в конкретные экраны и структуру данных. Продолжаем проектировать «Проектный навигатор». У Анны будет понятный путь подачи, у Ирины — путь рассмотрения. Затем свяжем элементы экранов с объектами и таблицами. Все изображения интерфейса являются подготовленными макетами.',
'В результате получим комплект экранов, объектную модель и схему базы. Сначала рассмотрим действия человека, затем выясним, какие значения нужны системе для их выполнения.','Кратко обозначьте результат и статус макетов.'),
S('Задача пользователя на экране','Каждый экран поддерживает определённый шаг сценария',T(['Требование','Задача','Экран'],[['ФТ-02','Выбрать подходящий проект','Каталог и карточка'],['ФТ-01','Передать мотивацию и увидеть приём','Форма и подтверждение'],['ФТ-03','Получить обращения своего проекта','Список преподавателя']]),
'Проектирование интерфейса начинается с задачи человека. Анна открывает каталог, чтобы выбрать проект. Карточка помогает понять содержание и условия. Форма нужна для передачи мотивации. Раздел своих заявок позволяет проверить результат позже. Если начать с набора красивых страниц, можно пропустить важный шаг. Например, форма будет работать, а возвращаться к поданной заявке окажется некуда. Поэтому сопоставим каждый экран с уже установленным требованием.',
'На одном экране могут сочетаться несколько действий, но основное должно быть различимо. Карточка проекта прежде всего объясняет предложение и условия участия. Кнопка подачи появляется в этом контексте. Пользователь не обязан помнить технический номер проекта, потому что уже выбрал его на предыдущем шаге. Эта связь уменьшает лишний ввод и поддерживает согласованность. Мы будем проверять её на всей последовательности макетов.','Проводите сравнение по строкам таблицы.'),
S('UX и UI','Опыт взаимодействия и видимые элементы интерфейса',T(['Понятие','Простое объяснение','Пример'],[['UX: user experience','Как человек проходит путь и воспринимает результат','Анна понимает, принята ли заявка'],['UI: user interface','Элементы, через которые человек взаимодействует','Поле, подпись, кнопка, сообщение']]),
'Ю-икс — сокращение от user experience, то есть пользовательский опыт. В нашем разборе это путь Анны, понятность действий и уверенность в результате. Ю-ай — user interface, пользовательский интерфейс: видимые и доступные элементы взаимодействия. Эти понятия связаны. Подпись кнопки относится к интерфейсу, но влияет на понимание следующего шага. Успешное сохранение без понятного подтверждения создаёт неудовлетворительный опыт даже при исправной серверной обработке.',
'Мы используем различие для проверки решений. Можно изменить цвет кнопки и не устранить потерю введённого текста при ошибке. Можно сократить число экранов и случайно убрать необходимые условия участия. Поэтому оценка не ограничивается внешним впечатлением. Важно, помогает ли интерфейс человеку достигнуть цели в конкретной ситуации, включая ожидание, отказ и возврат к результату. Такой подход задаёт содержание следующих макетов.','Произнесите «ю-икс» и «ю-ай», дайте расшифровки до сокращений.'),
S('Связь интерфейса и данных','Каждое показанное значение имеет источник',T(['На экране','Источник значения'],[['Сайт студенческого клуба','Название проекта'],['Анна Смирнова','Текущий пользователь'],['Мотивационный текст','Ввод Анны'],['На рассмотрении','Состояние сохранённой заявки'],['Дата подачи','Время создания записи']]),
'Макет показывает не только расположение элементов. Он предъявляет сведения, которые система должна получить или сформировать. Название проекта приходит из каталога. Имя определяется через текущего пользователя. Мотивацию вводит Анна. Начальный статус и дату назначает система. Это разные источники, поэтому одинаковые текстовые строки на макете не означают одинаковый способ ввода. Пользователь не заполняет то, что уже известно приложению.',
'Сопоставление помогает найти пробелы в модели. Если на экране появляется «Осталось мест», понадобится правило расчёта и источник вместимости. В согласованной первой версии такого поля нет. Мы не добавляем его ради привычного вида карточки. Так данные ограничивают произвольное оформление, а интерфейс помогает проверить достаточность модели. На этом занятии будем двигаться в обе стороны: от экрана к данным и от данных к экрану.','Не добавляйте неподтверждённые сведения о количестве мест.'),
S('Путь студента','Выбор, подача и возврат к результату',P(['Каталог','Анна видит доступные учебные проекты'],['Карточка','Читает описание и состояние набора'],['Форма','Вводит мотивацию для выбранного проекта'],['Мои заявки','Проверяет сохранение и позднее решение']),
'Путь пользователя — последовательность шагов для достижения цели. Здесь мы рассматриваем путь Анны. Каталог помогает выбрать объект, карточка — понять его, форма — выразить намерение, свои заявки — увидеть результат. После подачи путь не заканчивается навсегда: Анна возвращается за решением. Поэтому раздел своих обращений должен быть доступен независимо от краткого подтверждения. Если ссылку спрятать только в сообщении после отправки, повторный вход станет затруднительным.',
'Для каждого перехода известен смысл. Из каталога передаётся выбранный проект. Из формы возникает заявка. Возврат к каталогу не должен удалять уже сохранённую запись. Мы не рисуем каждый щелчок как самостоятельный экран, если он не меняет состояние. Карта нужна для проверки полноты сценария и точек, где пользователь получает подтверждение. Дальше разберём эти переходы конкретнее.','Сначала пройдите основной маршрут целиком.'),
S('Карта экранов','Переходы сохраняют выбранный контекст',D(['Каталог','Карточка проекта 17','Форма проекта 17','Подтверждение','Мои заявки'],[['Каталог','Карточка проекта 17','Выбор проекта'],['Карточка проекта 17','Форма проекта 17','Подать заявку'],['Форма проекта 17','Подтверждение','Успешное сохранение'],['Подтверждение','Мои заявки','Проверить заявку']]),
'Карта экранов показывает, куда ведёт действие и какие сведения сохраняются при переходе. После выбора проекта семнадцать Анна должна попасть в форму именно этого проекта. Отправка ведёт к подтверждению только при успешном сохранении. При ошибке длины она остаётся в форме и может исправить текст. Такая ветвь не показана как успешный переход. Для учебного маршрута этого достаточно, чтобы избежать нескольких типичных разрывов.',
'Контекст включает выбранный проект и уже введённую мотивацию. Если возврат после ошибки очищает поле, человеку придётся повторять работу. Если заголовок формы не называет проект, возрастает вероятность подачи не туда. Эти последствия не видны в отдельном красивом макете. Их можно обнаружить, только рассматривая переходы между состояниями и сопоставляя сведения на соседних экранах.','Показывайте сохранение номера проекта на первых трёх экранах.'),
S('Навигация','Основные разделы доступны повторно',T(['Элемент','Назначение','Ожидаемое поведение'],[['Каталог проектов','Начать выбор','Открывает общий каталог'],['Мои заявки','Проверить свои обращения','Показывает заявки текущего студента'],['Название проекта','Вернуться к описанию','Сохраняет связь с выбранным проектом']]),
'Навигация помогает человеку понять своё положение и перейти к нужному разделу. В нашем студенческом пути достаточно понятных ссылок на каталог и свои заявки. Их названия должны оставаться одинаковыми на разных страницах. Если один раздел назван «Мои заявки», а позже «Отклики», пользователь может решить, что это разные сущности. Мы сохраняем словарь предметной области. Технический адрес страницы не обязан быть виден вместо понятной подписи.',
'Навигационный элемент отличается от действия, меняющего данные. Ссылка на каталог просто открывает представление, а кнопка подачи создаёт заявку. Пользователь должен различать последствия. Для формы также важно предусмотреть возврат к карточке: чтение условий не должно требовать случайного поиска через историю браузера. Так мы поддерживаем непрерывность задачи без добавления лишних функций.','Объясните разницу перехода и изменения данных.'),
S('Порядок информации','Сначала задача и объект, затем ввод и действие',P(['Заголовок','Заявка на проект «Сайт студенческого клуба»'],['Подпись и инструкция','Почему вы хотите участвовать? От 50 до 1000 символов'],['Поле','Место для мотивационного текста'],['Действие','Подать заявку']),
'Порядок элементов задаёт последовательность понимания. Сначала Анна узнаёт, какую задачу решает и к какому проекту относится форма. Затем видит вопрос и ограничение. После этого вводит текст и выполняет действие. Если инструкцию поместить после кнопки или показать только при отказе, человек может потратить время на неподходящий текст. Это предотвратимая ошибка интерфейса. Требование к длине известно заранее и должно быть доступно до отправки.',
'На схеме выделена смысловая последовательность, а не единственное обязательное расположение в пикселях. На узком экране блоки могут занимать другую ширину. Их порядок и связь должны сохраняться. Изображение заголовка без связанного поля не решит задачу доступности, поэтому при реализации потребуется корректная структура элементов, а макет помогает заранее определить её смысл.','Пройдите сверху вниз, в порядке чтения формы. ',[refs.forms]),
S('Последовательность действий','Подтверждение появляется после результата обработки',P(['Заполнение','Анна вводит мотивационный текст'],['Отправка','Интерфейс показывает ожидание результата'],['Подтверждение','Система сообщает о сохранённой заявке'],['Проверка позже','Анна открывает свои заявки']),
'После нажатия кнопки возникает промежуточный этап. Интерфейс передал данные, но ещё ожидает ответ. В этот момент нельзя показывать окончательное подтверждение, потому что сервер может отказать. После успешного сохранения появится номер заявки и начальное состояние. Такая последовательность делает результат понятным и честным. Она также подготавливает человека к задержке, не вынуждая сразу нажимать кнопку повторно.',
'Промежуточная надпись должна описывать действие без обещания готового результата. «Отправляем заявку» подходит для ожидания. «Заявка сохранена» подходит только после подтверждения. Если связь прервалась, мы не превращаем отсутствие ответа в утверждение об отсутствии записи. Этот случай получит отдельный макет, потому что от него зависит безопасное дальнейшее действие пользователя.','Отделите ожидание от подтверждённого успеха.'),
S('Состав формы заявки','Пользователь вводит мотивацию, остальные значения уже определены',U('Форма заявки','empty',{kind:'form',description:'Заголовок с названием проекта, подпись поля, пустое поле, инструкция 50–1000 символов, кнопка «Подать заявку».'}),
'На экране подготовлена форма для проекта семнадцать. Анна вводит только мотивацию. Проект известен из карточки, а пользователь — из действующего входа. Система назначит статус и дату после успешной обработки. Поэтому поля «Ваш номер», «Статус» и «Дата подачи» в этой форме отсутствуют. Если заставить человека вводить их вручную, появятся лишние ошибки и возможность передать чужое значение. Сокращение ввода здесь опирается на распределение ответственности.',
'Подпись сообщает, что именно ожидают от текста. Подсказка заранее задаёт обе границы. Кнопка называет действие, которое меняет данные. Макет не включает загрузку файла: это пожелание было отложено на первом занятии. Мы показываем полный состав согласованной первой версии и можем проверить каждую деталь по источнику значения. Позже форма станет исходной точкой создания объекта заявки.','Покажите отсутствие технических полей, не вводите их в макет.',[refs.forms]),
S('Обязательные поля и границы','Пустое значение и недопустимая длина имеют понятное объяснение',T(['Значение','Оценка длины','Результат проверки поля'],[['Пустая строка','0 символов','Нужен мотивационный текст'],['Короткий текст','49 символов','Не выполнен минимум'],['Допустимая нижняя граница','50 символов','Условие длины выполнено'],['Допустимая верхняя граница','1000 символов','Условие длины выполнено'],['Слишком длинный текст','1001 символ','Превышен максимум']]),
'Обязательность означает, что нужное значение должно присутствовать. Для мотивации этого недостаточно: необходимо ещё выполнить ограничение длины. Оба конца диапазона включены. Ровно пятьдесят и ровно тысяча символов удовлетворяют именно правилу длины, но не отменяют остальных условий подачи. Проект должен оставаться открытым, а предыдущая заявка — отсутствовать. Поэтому мы не называем длину единственным критерием успеха.',
'Для учебного договора считаем длину по Unicode code points после удаления пробельных символов с концов. Это уточнение согласует счётчик и сервер для граничных примеров. Сложные составные символы в такой модели могут восприниматься как один знак, но состоять из нескольких точек. В демонстрационных граничных строках используются обычные русские буквы без этих неоднозначностей.','Не утверждайте, что 50 символов гарантируют полное успешное создание.'),
S('Тексты интерфейса','Сообщение называет причину и следующий шаг',T(['Недостаточно ясно','Подготовленный вариант'],[['Ошибка','Добавьте описание: минимум 50 символов. Сейчас введено 32'],['Что-то пошло не так','Вы уже подали заявку на этот проект. Откройте «Мои заявки»'],['Недоступно','Проект закрыт и больше не принимает новые заявки']]),
'Текст интерфейса помогает исправить конкретную ситуацию. В первом примере человек должен понять, что текст слишком короткий, узнать границу и дополнить поле. Во втором увеличение текста не поможет, потому что заявка уже существует. Здесь полезен переход к сохранённой записи. В третьем проблема относится к проекту, а не к содержимому формы. Такие различия должны поддерживаться результатами обработки, иначе интерфейс будет угадывать причину.',
'На слайде число тридцать два относится к условному примеру сообщения, а не к строке мотивации из последующих макетов. Важно не выдавать случайное число за реально рассчитанную длину. При реализации счётчик формируется из текущего значения по общему правилу подсчёта. На экране также сохраняется введённый текст, чтобы отказ не заставлял Анну начинать заново.','Назовите сообщения готовыми вариантами для разных причин.',[refs.forms]),
S('Визуальная иерархия','Главное действие и связанная инструкция различимы',T(['Элемент','Роль в восприятии','Решение'],[['Заголовок','Назвать задачу','Крупнее пояснений'],['Подпись поля','Связать вопрос и ввод','Рядом с полем'],['Ограничение','Помочь подготовить текст','Видно до отправки'],['Кнопка','Показать основное действие','Выделена и подписана']]),
'Визуальная иерархия показывает относительную важность элементов. На форме прежде всего различимы задача, поле и действие. Дополнительное пояснение не должно конкурировать с заголовком. Иерархию создают размер, расположение и интервалы. Она полезна, когда помогает быстро понять порядок работы. Случайное выделение декоративной детали может, напротив, отвлечь от важного условия. Поэтому оформление связываем с целью экрана, а не с желанием заполнить пустое место.',
'Сравним смысл одинаково крупных элементов. Если инструкция длины выглядит как второстепенная сноска и расположена далеко, человек может её не заметить. Если вся форма набрана крупным жирным текстом, главный элемент теряется. На подготовленном макете ограничение находится у поля, а действие выделено отдельно. Эти решения поддерживают конкретный путь заполнения.','Указывайте на один элемент за раз.'),
S('Читаемость','Размер и длина строки помогают воспринимать содержание',T(['Вариант','Последствие'],[['Плотный абзац мелким шрифтом','Труднее найти условие участия'],['Короткое описание с ясными абзацами','Удобнее понять содержание проекта'],['Длинное техническое название без переноса','Возможен выход за границу узкого экрана']]),
'Читаемость зависит от размера, длины строки, интервалов и структуры текста. Мы не можем гарантировать удобство одной цифрой размера шрифта для всех устройств. Нужно смотреть на реальные условия. В карточке проекта человеку важно различить описание, преподавателя и доступность набора. Если всё сжато в плотный абзац, поиск нужного условия затрудняется. Подготовленный макет использует короткие смысловые группы и сохраняет возможность переноса строк.',
'Технические фрагменты требуют отдельного внимания. Номер заявки короткий, а адрес операции может быть длинным. При уменьшении ширины он не должен выталкивать весь экран. В презентации достаточно показать проблему и исправленный вариант. При разработке пригодность проверяют на фактических размерах окна и с увеличенным текстом. Это отличается от произвольного уменьшения шрифта ради размещения всего на одном экране.','Сравнивайте конкретное условие чтения, не вкусы оформления.'),
S('Контраст','Текст должен различаться на своём фоне',T(['Пара','Учебное значение','Вывод'],[['#777777 на белом','Около 4,48:1','Чуть ниже 4,5:1 для обычного текста'],['#444444 на белом','Около 9,74:1','Выше минимального порога'],['Обычный текст WCAG AA','Не менее 4,5:1','Порог относится к заданным условиям']]),
'Контраст показывает различие яркости текста и фона. В рекомендациях WCAG уровня AA для обычного текста используется порог четыре с половиной к одному. Для крупного текста предусмотрены другие условия, поэтому нельзя переносить одно число на все элементы. На слайде два рассчитанных сочетания. Серый семьдесят семь на белом выглядит привычно, но немного не достигает порога обычного текста. Более тёмный сорок четыре даёт заметно больший запас.',
'Числа здесь относятся к конкретным цветовым значениям, а не к исследованию пользователей. Вывод тоже ограничен: достаточный контраст не гарантирует понятность подписи или удобство всей формы. Он устраняет одну проверяемую проблему восприятия. Если состояние передаётся цветом, дополнительно потребуется текстовая подпись. Эту задачу рассмотрим следующим шагом на статусах заявки.','Не применяйте порог 4,5:1 ко всем графическим элементам.',[refs.contrast]),
S('Цвет и смысл состояния','Подпись сохраняет значение независимо от восприятия цвета',T(['Состояние','Текст','Дополнительное различие'],[['pending','На рассмотрении','Отдельная плашка ожидания'],['accepted','Одобрена','Положительная подпись'],['rejected','Отклонена','Отрицательная подпись']]),
'Цвет может помогать различать состояния, но смысл должен быть доступен и без него. Если одобрение и отказ обозначены только зелёным и красным кружком, часть пользователей не сможет уверенно прочитать результат. Поэтому состояние сопровождается точной подписью. Для нашего примера используем уже согласованные три текста. Оттенок является дополнительным визуальным признаком, а не единственным носителем решения.',
'Сохранение словаря важно и для обычного чтения. Надпись «Готово» непонятна: она может означать отправку формы или положительное решение преподавателя. «Одобрена» однозначно относится к рассмотрению. При загрузке списка нельзя заранее показывать прежний цвет как подтверждение актуального статуса. Интерфейс сначала должен получить сведения и затем отобразить согласованное состояние заявки.','Прочитайте подписи без упоминания цветов.',[refs.forms]),
S('Подписи элементов','Название поля остаётся видимым при вводе',T(['Решение','Пользовательское последствие'],[['Подпись над полем','Вопрос остаётся видимым после ввода'],['Только подсказка внутри поля','Текст подсказки исчезает при заполнении'],['Программная связь подписи и поля','Средства доступа могут определить назначение элемента']]),
'Поле мотивации должно иметь устойчивую подпись. Текст внутри пустого поля может показать пример, но после ввода он исчезает. Человек теряет видимый вопрос. Поэтому подпись «Почему вы хотите участвовать?» расположена отдельно. При реализации её связывают с элементом ввода, чтобы назначение было доступно не только зрительно. Макет показывает положение и смысл, а корректная разметка обеспечивает техническую связь.',
'Подсказка диапазона дополняет подпись, а сообщение ошибки указывает, что исправить. У этих текстов разные задачи, поэтому один не должен бесследно заменять другой. Когда текст введён, Анна всё ещё должна видеть вопрос и допустимую длину. Такая структура особенно полезна при возврате к форме после отказа, когда человеку нужно быстро восстановить контекст.','Покажите, что подпись находится вне поля.',[refs.forms]),
S('Работа с клавиатурой','Путь можно пройти без указателя мыши',P(['Tab','Переводит фокус между доступными элементами'],['Shift + Tab','Возвращает к предыдущему элементу'],['Ввод','Активирует выбранное действие по правилам элемента']),
'Пользователь может работать с клавиатуры по разным причинам. Важно, чтобы нужные действия оставались доступны. На нашей форме последовательность фокуса соответствует смысловому порядку: навигация, поле мотивации, кнопка подачи. Неактивные декоративные элементы не должны прерывать этот путь. Проверка включает не только возможность нажать кнопку, но и отсутствие ловушки, из которой нельзя выйти обычным переходом.',
'Клавиши активации зависят от типа элемента. Поэтому при реализации предпочтительны подходящие стандартные элементы, у которых известное поведение. На слайде мы показываем общий путь, а не требуем от аудитории его выполнить. В подготовленной демонстрации ведущий последовательно указывает, куда переместился бы фокус. Следующий слайд покажет, почему само положение фокуса должно быть видно.','Демонстрируйте подготовленную последовательность указанием.',[refs.keyboard]),
S('Видимый фокус','Человек понимает, какой элемент получит действие',U('Форма с фокусом','focus',{kind:'form',description:'Поле мотивации окружено заметной синей рамкой фокуса; подпись и ограничение сохранены.'}),
'Фокус обозначает элемент, который сейчас получает ввод или активацию с клавиатуры. Если его положение не видно, человек не понимает, что произойдёт после нажатия. На макете поле выделено рамкой, которая отличается от обычной границы. Выделение не сообщает ошибку и не меняет состояние заявки. Оно показывает текущее место взаимодействия. Поэтому цвет фокуса не должен быть единственным обозначением отказа или успеха.',
'В готовой реализации проверяют последовательность, видимость и отсутствие перекрытия важного элемента. Одного снимка недостаточно, чтобы доказать доступность всего сценария. Наш макет фиксирует требуемый вид состояния, а последующая проверка должна пройти все нужные элементы. Это ещё один пример связи проектного решения и критерия: сначала задаём, что человек должен различить, затем наблюдаем это в работающем интерфейсе.','Не называйте рамку фокуса ошибкой поля.',[refs.focus]),
S('Узкий экран','Порядок и доступность действий сохраняются при уменьшении ширины',T(['Изменение','Что сохраняем'],[['Элементы перестраиваются в один столбец','Порядок задачи, поля и кнопки'],['Описание переносится','Видимость полного смысла'],['Кнопки получают достаточное место','Доступность основного действия'],['Появляется вертикальная прокрутка','Отсутствие необходимости прокручивать всю страницу по горизонтали']]),
'На узком экране нельзя просто пропорционально уменьшить весь интерфейс. Текст станет слишком мелким, а действие труднодоступным. Вместо этого блоки перестраиваются. Заголовок остаётся перед полем, инструкция рядом с ним, кнопка доступна после ввода. Вертикальная прокрутка допустима, если порядок понятен. Для обычной формы горизонтальное перемещение всей страницы создаёт лишние трудности и обычно указывает на неудачное размещение.',
'Содержание проекта и правила не меняются вместе с шириной окна. Нельзя скрыть ограничение длины только потому, что оно не помещается в прежней строке. В подготовленном сравнении мы переносим подпись и описание, а не удаляем их. При реализации проверяют фактическую работу с увеличением и разными размерами. Макет фиксирует принцип, который должна поддержать вёрстка.','Не обещайте адаптивность по одному широкому скриншоту.'),
S('Каталог проектов','Первый экран помогает выбрать объект',U('Каталог проектов','default',{kind:'catalog',description:'Заголовок «Каталог проектов», карточка проекта 17 с названием и преподавателем; переход в описание проекта.'}),
'Начинаем подготовленную последовательность из десяти экранов. Анна находится в каталоге. Для каждого проекта важны название и краткое описание, чтобы отличить его от соседних. Каталог заранее заполнен, поэтому создание карточек не входит в этот путь. Проект «Сайт студенческого клуба» имеет номер семнадцать, но для выбора важнее его название и содержание. Технический номер помогает нам проследить пример между материалами.',
'Выбор карточки ещё не создаёт заявку. Это переход к дополнительной информации. Мы не добавляем автоматическую подачу при просмотре, потому что человек ещё не выразил намерение и не ввёл мотивацию. Счётчик просмотров тоже не является полем базовой заявки. Если позже понадобится аналитика, события будем проектировать отдельно. Сейчас каталог выполняет одну понятную роль: даёт выбрать существующий проект и перейти к его условиям.','Назовите первый экран и конкретный выбранный проект.'),
S('Карточка проекта','Описание предшествует решению о подаче',U('Карточка проекта','default',{kind:'project',description:'Проект 17, название, описание задачи, преподаватель Ирина Павлова; набор открыт; действие «Подать заявку».'}),
'Анна открыла описание проекта семнадцать. Теперь видит задачу разработки каталога мероприятий и личного кабинета участника. Преподаватель указан по данным проекта. Состояние набора показывает, можно ли начать подачу. Кнопка связана именно с этой карточкой. При переходе приложение сохранит выбранный номер, поэтому Анне не придётся выбирать тему повторно из общего списка. Так интерфейс использует уже выполненное действие.',
'Карточка не обещает одобрение. Открытый набор означает только допустимость новой заявки при соблюдении остальных правил. Результат рассмотрения зависит от отдельного действия преподавателя. Если текст кнопки заменить на «Участвовать», можно создать неверное ожидание немедленного зачисления. Подпись «Подать заявку» точнее выражает последствие и согласуется с будущим начальным состоянием. На следующем экране появится форма выбранного проекта.','Различайте открытый набор и положительное решение.'),
S('Пустая форма','Проект известен до ввода мотивации',U('Пустая форма заявки','empty',{kind:'form',description:'Название проекта сохранено, поле мотивации пустое, обе границы длины видны перед кнопкой.'}),
'Форма открылась из конкретной карточки. Заголовок подтверждает, что Анна по-прежнему работает с сайтом студенческого клуба. Поле пока пустое. Перед началом ввода видна инструкция от пятидесяти до тысячи символов. Номер студента отсутствует, потому что личность определяется по входу. Статус тоже отсутствует как редактируемое поле. До успешного сохранения мы ещё не создали заявку, поэтому не показываем ей окончательный номер.',
'Пустой экран отличается от отсутствия данных в каталоге. Здесь пустота ожидаема: пользователь ещё не написал текст. Интерфейс должен объяснить, что сделать дальше. Не требуется тревожная ошибка сразу при открытии формы, если человек ещё не пытался её отправить. Можно спокойно показать ограничение и назначение поля. После попытки с недопустимым значением сообщение станет конкретным и связанным с текущим содержимым.','Отметьте отсутствие номера заявки до сохранения.'),
S('Заполненная форма','Мотивация относится к выбранному проекту',U('Заполненная форма заявки','filled',{kind:'form',description:'Введён текст о каталоге мероприятий и личном кабинете участника; подпись и инструкция остаются видны.'}),
'Анна подготовила мотивацию: «Хочу разработать каталог мероприятий и личный кабинет участника студенческого клуба». Это полный учебный текст, который будем использовать в запросе на третьем занятии. Его длина находится внутри согласованного диапазона. На слайде не показан счётчик с произвольным числом. Если счётчик понадобится, он должен вычисляться по тому же правилу, что серверная проверка. Содержание связывает интерес студентки с задачей проекта.',
'Заполнение формы ещё не означает регистрацию. Данные пока находятся в интерфейсе. Поэтому раздел своих заявок не должен показывать эту попытку как принятую до успешного ответа. Мы также не меняем название проекта при вводе. Сохранение контекста позволяет человеку проверить, куда пойдёт мотивация. Именно эти два значения — выбранный проект и текст — позже составят тело учебного запроса.','Прочитайте учебную мотивацию один раз целиком.'),
S('Отправка формы','Интерфейс показывает ожидание подтверждения',U('Отправка заявки','sending',{kind:'form',description:'Текст сохранён в поле, действие временно недоступно, подпись «Отправляем заявку…» обозначает ожидание.'}),
'После нажатия интерфейс передаёт данные и ожидает результат. Подпись «Отправляем заявку» показывает текущую работу. Временно недоступная кнопка уменьшает случайные повторы в этом окне. Однако она не гарантирует единственность записи: пользователь может открыть вторую вкладку. Поэтому это решение относится к удобству, а правило повторов поддерживается сервером и данными. Дальше рассмотрим его техническую защиту на третьем вебинаре.',
'Во время ожидания мотивация остаётся доступной в состоянии формы. Если связь прервётся, интерфейс сможет сохранить текст для дальнейшего действия. Не следует немедленно очищать поле после нажатия: до подтверждения неизвестно, удалось ли завершить подачу. Промежуточное состояние не должно показывать «На рассмотрении» как уже полученный результат. Это название относится к сохранённой заявке и появляется после успешной обработки.','Покажите различие между подписью кнопки и статусом заявки.'),
S('Подтверждение подачи','Показан результат успешного сохранения',U('Подтверждение подачи','success',{message:'Заявка сохранена',description:'После успешной обработки показаны подтверждение, номер 104, проект 17, начальный статус и переход к своим заявкам.'}),
'Система подтвердила успешное сохранение. Теперь можно показать номер сто четыре и статус «На рассмотрении». Номер появился после создания записи и позволяет различать обращения. Подтверждение не означает, что Ирина уже прочитала мотивацию. Оно означает регистрацию. Переход в свои заявки даёт возможность увидеть результат в устойчивом разделе, а не только в кратком сообщении. Это реализация критерия ФТ-01.',
'На этом шаге меняется наш способ говорить об объекте. Раньше была форма и попытка подачи. Теперь есть сохранённая заявка. Она связана с Анной и проектом семнадцать, имеет дату и начальное состояние. Если страницу закрыть, запись должна остаться. Поэтому подтверждение опирается на данные системы, а не на локальное предположение браузера. Следующий экран покажет, как этот результат доступен при повторном обращении.','Не называйте регистрацию одобрением участия.'),
S('Мои заявки','Студент возвращается к сохранённому обращению',U('Мои заявки','pending',{kind:'applications',description:'В своём списке Анна видит заявку 104 на проект 17 и статус «На рассмотрении»; чужих обращений нет.'}),
'Раздел «Мои заявки» показывает обращения текущего студента. Анна видит заявку сто четыре на сайт студенческого клуба. Список нужен и сразу после подачи, и при последующем входе. Его содержание определяется пользователем, которого установила система. Нельзя просто показать все записи и скрыть чужие визуально. Право доступа должно ограничивать выдачу данных. Техническую сторону этого решения разберём вместе с запросом получения своих заявок.',
'На этом экране дата и статус имеют самостоятельное назначение. Дата помогает различать время подачи, статус — понять результат рассмотрения. Они не редактируются студентом. Если Анна подаст заявку на другой проект, в списке появится отдельная строка с другим проектом. Это допустимая ситуация, которая не нарушает запрет повторной пары. Следующий экран сменит точку зрения на преподавателя.','Уточните, что список принадлежит текущему студенту.'),
S('Список преподавателя','Ирина видит обращения на собственный проект',U('Заявки на мой проект','pending',{kind:'applications',role:'teacher',description:'Ирина Павлова открыла проект 17; показана заявка Анны 104, ожидающая рассмотрения.'}),
'Теперь текущим пользователем является Ирина Павлова. Она открывает обращения к своему проекту семнадцать. В списке есть заявка Анны сто четыре. Это та же запись, которую Анна видела в своём разделе. Мы не создавали копию для преподавателя. Разница состоит в цели представления и доступных действиях. Студент следит за собственным обращением, преподаватель готовится принять решение.',
'Принадлежность проекта существенна. Если другой преподаватель попытается открыть этот список, система должна проверить право, а не полагаться на наличие ссылки. Макет фиксирует корректную ситуацию, но полный проект включает также отказ. В списке полезно показать имя студента и текущее состояние, чтобы Ирина могла выбрать обращение для чтения. Мотивацию целиком можно открыть в подробном представлении, не перегружая общий список.','Явно смените текущего пользователя с Анны на Ирину.'),
S('Просмотр заявки','Сведения достаточны для принятия решения',U('Просмотр заявки','pending',{kind:'decision',role:'teacher',description:'Заявка 104, Анна, проект 17, полный мотивационный текст, состояние ожидания и два допустимых решения.'}),
'Ирина открыла заявку. На экране видны студент, проект и мотивация. Эти сведения помогают принять осмысленное решение. Две кнопки отражают допустимые переходы из ожидания: одобрить или отклонить. Здесь нет свободного поля статуса, в которое можно написать любое слово. Интерфейс поддерживает конечный набор действий, заранее согласованный в модели. Тем самым он снижает вероятность случайной ошибки пользователя.',
'Однако две кнопки сами по себе не доказывают полномочия. При обработке система снова проверит роль, принадлежность проекта и актуальное исходное состояние. С момента открытия экран мог устареть. Если решение уже принято в другом окне, повторное действие не должно молча перезаписать итог. Пока мы видим корректное исходное состояние. Следующий подготовленный экран покажет результат положительного решения.','Читайте сведения до кнопок решения.'),
S('Решение сохранено','Итоговое состояние больше не предлагает повторного рассмотрения',U('Результат решения','accepted',{kind:'decision',role:'teacher',description:'После сохранения положительного решения статус «Одобрена», сообщение об успехе; кнопки повторного решения отсутствуют.'}),
'После обработки решения система показывает «Одобрена». Для первой версии это итоговое состояние. Интерфейс больше не предлагает те же кнопки как обычный способ изменить результат. Отсутствие кнопок отражает правило, но окончательная защита остаётся на сервере. Если Анна обновит свои заявки, она получит тот же итог. Речь идёт об изменении одной общей записи, поэтому два представления должны согласоваться.',
'Отрицательное решение работает по тому же принципу перехода, но имеет другое итоговое значение и понятную подпись «Отклонена». Мы не добавляем автоматическую повторную подачу или обсуждение через чат. Эти возможности не входят в согласованную версию. Последовательность десяти экранов завершена: от выбора существующего проекта до сохранённого результата преподавателя. Теперь отдельно разберём состояния, которые основной успешный путь не показал.','Не добавляйте кнопку «Пересмотреть» в базовый макет.'),
S('Состояния интерфейса и заявки','Ожидание запроса отличается от ожидания решения',T(['Надпись','Объект состояния','Смысл'],[['Отправляем заявку…','Интерфейс','Ожидаем ответ обработки'],['На рассмотрении','Заявка','Запись существует, решения ещё нет'],['Не удалось получить ответ','Интерфейс','Результат операции неизвестен'],['Отклонена','Заявка','Сохранено отрицательное решение']]),
'На экране могут появляться похожие по смыслу слова ожидания. Их нужно относить к разным объектам. «Отправляем заявку» описывает текущую работу формы. «На рассмотрении» описывает уже существующую заявку. «Не удалось получить ответ» сообщает о неопределённости интерфейса. «Отклонена» является подтверждённым результатом преподавателя. Смешение этих уровней приводит к ложным сообщениям и неправильным действиям после сбоя.',
'Рассмотрим обрыв после сохранения. Интерфейс ещё не знает о результате, хотя в базе уже есть pending. Поэтому он не должен заменять свою неопределённость отрицательным статусом заявки. При восстановлении связи можно получить список и обнаружить существующую запись. Так один пример связывает видимое сообщение с моделью данных, а позже — с серверной обработкой и сопровождением.','Покажите столбец «Объект состояния» как главное различие.'),
S('Загрузка данных','Интерфейс сообщает, что содержимое ещё не получено',U('Загрузка моих заявок','loading',{kind:'applications',description:'Заголовок раздела уже виден, на месте списка сообщение «Загружаем заявки…»; пустой список не утверждается.'}),
'При открытии своих заявок системе нужно получить актуальные сведения. Пока ответ не пришёл, интерфейс показывает загрузку. Это отличается от состояния «Заявок пока нет». В первом случае мы ещё не знаем содержимое, во втором получили пустой результат. Если сразу рисовать отсутствие заявок, Анна может решить, что сохранённое обращение исчезло. Поэтому промежуточный экран должен честно описывать известное состояние.',
'Загрузка также не означает ошибку и не меняет статус заявки. В реализации она может длиться мало или заметно дольше в зависимости от условий. Мы не изображаем на слайде реальное измерение скорости. Подготовленный макет фиксирует содержание обратной связи. После успешного ответа список заменит сообщение. После отказа появится отдельное объяснение с возможным дальнейшим действием.','Не называйте загрузку отсутствием записей.'),
S('Отсутствие данных','Полученный пустой список помогает начать нужное действие',U('Пустой список заявок','empty',{kind:'applications',description:'После успешного получения пустого списка показано «Заявок пока нет. Выберите проект в каталоге».'}),
'Предположим, Анна ещё ничего не подавала, и система успешно получила пустой список. Сообщение «Заявок пока нет» теперь обосновано. К нему полезно добавить переход к каталогу, чтобы человек понимал следующий шаг. Пустота здесь нормальна и не требует тревожного оформления. Она означает отсутствие собственных записей при корректном доступе, а не отсутствие всех заявок во всей системе.',
'Если доступ запрещён или запрос не завершился, показывать этот же текст нельзя. Он скрыл бы проблему и сообщил неверные сведения. Поэтому пустое состояние проектируется отдельно от загрузки и ошибки. Для преподавателя отсутствие обращений своего проекта также может быть нормальным результатом. Текст должен соответствовать роли и объекту списка, сохраняя смысл исходного сценария.','Оговорите, что пустой ответ уже успешно получен.'),
S('Ошибка заполнения','Текст остаётся на месте, исправление указано рядом',U('Короткая мотивация','short',{kind:'form',description:'В поле 31 символ, под полем указаны минимум 50 и текущая длина 31; текст не удалён.'}),
'Подготовленный макет показывает текст «Хочу создавать сайты для клуба». В нём тридцать один символ с пробелами и точкой, поэтому он не достигает минимума. Сообщение называет обе величины и предлагает добавить описание. Поле сохраняет содержание. Анне не нужно вспоминать, что она уже написала. Это конкретный отказ по данным формы, поэтому его можно исправить до следующей попытки. Название проекта и остальные условия остаются прежними.',
'Мы специально согласовали число в сообщении с показанной строкой. Если иллюстрация говорит «введено 32», а фактически содержит другой объём, пример вводит в заблуждение. В работающем интерфейсе значение рассчитывается автоматически. В учебном макете оно проверено заранее. Условие длины затем повторно проверит сервер, потому что данные можно отправить и в обход этой формы.','Прочитайте сообщение как готовый текст пользователю.',[refs.forms]),
S('Повторная подача в интерфейсе','Сообщение ведёт к уже существующей заявке',U('Повторная заявка','error',{message:'Вы уже подали заявку на этот проект. Откройте «Мои заявки».',description:'После повторной попытки система сообщает о существующей заявке; новая запись не показана как созданная.'}),
'У Анны уже существует заявка на проект семнадцать. Повторное действие не создаёт ещё одну запись. Пользователь получает объяснение и путь к сохранённому обращению. Это полезнее общего сообщения об ошибке: человек понимает, что его предыдущая попытка учтена. Если первый ответ потерялся, такое поведение помогает восстановить уверенность. Номер существующей заявки можно получить через свои заявки, соблюдая право доступа.',
'Сообщение не должно утверждать, что Анна не вправе подавать другие обращения вообще. Ограничение относится к тому же проекту. Также нельзя автоматически очищать данные и приглашать повторять попытку бесконечно. Система должна направить к проверке уже сохранённого результата. Позже в договоре API этому случаю будет соответствовать конфликт с текущим состоянием и код APPLICATION_EXISTS.','Не показывайте повторную подачу как второй успешный запрос.'),
S('Закрытый набор на экране','Карточка объясняет, почему новая подача недоступна',U('Закрытый проект','closed',{kind:'project',description:'Проект 17 отмечен как закрытый; действие подачи недоступно с понятной подписью; описание остаётся читаемым.'}),
'При закрытом наборе карточка остаётся понятной, но новая подача недоступна. Одного серого прямоугольника вместо кнопки недостаточно: пользователь может не понять причину. Подпись «Набор закрыт» связывает ограничение с состоянием проекта. Существующая заявка Анны не исчезает. Она по-прежнему доступна в своём разделе. Мы сохраняем различие между возможностью нового обращения и результатом уже принятого.',
'Если форму открыли заранее, её исходные сведения могли устареть. Поэтому даже при видимой доступности кнопки сервер проверит актуальное состояние проекта. В случае отказа текст нужно сохранить и объяснить причину. Подготовленная карточка показывает нормальное представление закрытого набора, а не исчерпывает все возможные условия получения отказа. Эти условия будут включены в проверки четвёртого вебинара.','Не меняйте статус существующей заявки вслед за набором.'),
S('Неопределённый результат при обрыве связи','Отсутствие ответа не доказывает отсутствие записи',U('Не удалось подтвердить результат','unknown',{kind:'form',description:'Мотивация сохранена в форме; сообщение не утверждает отсутствие заявки и предлагает проверить свои заявки после восстановления связи.'}),
'Сложный случай: Анна отправила форму, сервер мог успеть сохранить запись, но ответ не дошёл. Интерфейс не располагает достаточными сведениями. Поэтому сообщение «Заявка не сохранена» было бы необоснованным. Корректнее сказать, что результат пока не удалось подтвердить. Введённый текст сохраняется, а после восстановления связи приложение получает свои заявки. Если запись уже существует, Анна увидит номер сто четыре.',
'Такой путь предотвращает лишние попытки и неверные ожидания. Если повторный запрос всё же отправлен, правило уникальности защитит от второй записи, но интерфейс должен обработать конфликт понятно. Мы не называем сбой сети итоговым статусом. На третьем занятии проследим техническую последовательность, а на четвёртом разберём её по журналам и сведениям о запросе. Здесь фиксируем честный пользовательский текст.','Не сообщайте «не сохранена», пока это не установлено.'),
S('Отображение статуса заявки','Данные системы преобразуются в согласованную подпись',T(['Полученное значение','Текст интерфейса','Допустимое действие'],[['pending','На рассмотрении','Ирина может принять итоговое решение'],['accepted','Одобрена','Повторное рассмотрение отсутствует'],['rejected','Отклонена','Повторное рассмотрение отсутствует']]),
'Интерфейс получает машинное значение и показывает понятное человеку название. Соответствие фиксировано: pending означает ожидание, accepted — одобрение, rejected — отказ. Если разработчик произвольно покажет «Завершена» для обоих итогов, пользователь потеряет важное различие. Поэтому словарь подписей является частью проекта. Одновременно он определяет доступные действия: окончательные состояния не предлагают обычного повторного решения.',
'Неизвестное значение не следует молча превращать в одно из трёх известных. Оно может означать несовместимость версии или ошибку данных. В нашем учебном договоре допустимы ровно три состояния. Их ограничение позже отразим в таблице заявок. Так одно правило имеет проявление в интерфейсе, модели, хранении и обработке. Мы завершили разбор состояний и теперь перейдём к самим объектам.','Произнесите машинное значение и русскую подпись рядом.'),
S('Объект и класс','Конкретный участник отличается от описания общего типа',T(['Понятие','В учебном сервисе','Что означает'],[['Класс','Пользователь','Общее описание сведений и допустимого поведения'],['Объект','Анна Смирнова, id 12','Конкретный пользователь с собственными значениями'],['Другой объект того же класса','Ирина Павлова, id 7','Другая запись с другим набором значений']]),
'Объект представляет конкретный предмет или участника в модели. Класс задаёт общее описание объектов одного вида: какие сведения у них есть и какое поведение с ними связано. Анна и Ирина — разные объекты класса пользователя. У обеих есть идентификатор, имя, почта и роль, однако значения различаются. Класс не является ещё одной строкой рядом с Анной. Он описывает структуру и смысл таких объектов.',
'Объектная модель помогает обсуждать предметную область до выбора таблиц. Не каждый класс обязательно превращается в отдельную таблицу без изменений. Мы сначала определяем, что означают пользователь, проект и заявка, а затем выберем способ хранения. Такое разделение позволяет не путать смысл объекта с конкретным техническим представлением и точнее объяснить связи между ними.','Привяжите оба термина к Анне, затем к Ирине.'),
S('Объект «Пользователь»','Личность, контакт и роль имеют разные назначения',T(['Поле','Анна','Ирина'],[['id','12','7'],['full_name','Анна Смирнова','Ирина Павлова'],['email','anna@example.test','irina@example.test'],['role','student','teacher']]),
'Пользователь содержит сведения, необходимые для идентификации и роли. Идентификатор отличает запись независимо от совпадения имён. Полное имя показывают человеку. Электронная почта является контактным значением, а роль задаёт характер допустимых действий. Учебные адреса используют домен example.test и не предназначены для настоящей переписки. Мы не добавляем сюда мотивацию: она относится к конкретной заявке, а не к человеку вообще.',
'Роль не заменяет проверку принадлежности проекта. Значение teacher говорит, что пользователь преподаватель, но ещё не даёт доступ ко всем обращениям. Нужна связь с проектом через teacher_id. В этой модели у пользователя одна роль, как зафиксировано для учебного сценария. Возможность нескольких ролей была бы отдельным изменением, которое повлияло бы на правила доступа и представления.','Все адреса условные. Читайте назначения полей, а не почту по буквам.'),
S('Объект «Проект»','Описание и доступность набора принадлежат проекту',T(['Поле','Значение проекта 17'],[['id','17'],['title','Сайт студенческого клуба'],['description','Каталог мероприятий и личный кабинет участника'],['teacher_id','7'],['is_open','true']]),
'Проект хранит название, описание, ответственного преподавателя и доступность новых заявок. Значение teacher_id равно семи и связывает его с Ириной. Логическое поле is_open имеет два значения: true для открытого набора и false для закрытого. Оно не определяет итог отдельной заявки. Этот итог находится в другом объекте. Так мы разделяем свойства предложения и состояние обращения конкретного студента.',
'Название может измениться при редакционной правке, а идентификатор остаётся ссылкой на тот же проект. Поэтому связь заявки не строят только по строке названия. Два проекта теоретически могут иметь похожие названия, и переименование не должно разрушать историю. В учебной версии каталог заполнен заранее. Мы показываем состав объекта, но не добавляем отдельный экран редактирования, которого нет в согласованном пути.','true — «тру», false — «фолс», объясните оба значения.'),
S('Объект «Заявка»','Один объект связывает студента, проект и рассмотрение',T(['Поле','Заявка Анны после создания'],[['id','104'],['project_id / student_id','17 / 12'],['motivation',motivation],['status','pending'],['created_at','2026-10-15T10:00:00Z · условное время']]),
'Заявка появляется после успешной подачи. В ней сохраняются ссылки на выбранный проект и текущего студента, мотивация, статус и время создания. Для примера используем номер сто четыре. Указанное время условное и записано с обозначением UTC. Это не время фактически проведённой операции. Статус назначает система, а текст берётся из формы. Распределение источников совпадает с тем, что мы установили при разборе интерфейса.',
'Заявка не хранит копию полного имени преподавателя и описания проекта. Их можно получить через связи. Это уменьшает число мест, которые потребовалось бы исправлять при изменении названия. Однако проект должен сохранять устойчивый идентификатор, а связанные записи — оставаться согласованными. Следующие схемы покажут, как несколько объектов образуют модель и какие ограничения из этого следуют.','Условную дату не представляйте как журнал работающего приложения.'),
S('Связи объектов','Заявка ссылается на конкретные объекты',D(['Анна, пользователь 12','Заявка 104','Проект 17','Ирина, пользователь 7'],[['Заявка 104','Анна, пользователь 12','Подал студент'],['Заявка 104','Проект 17','Выбранный проект'],['Проект 17','Ирина, пользователь 7','Ответственный преподаватель']]),
'Прочитаем объектную схему начиная с заявки. Она принадлежит Анне и относится к проекту семнадцать. Сам проект связан с Ириной как ответственным преподавателем. Поэтому право Ирины на решение определяется не прямым произвольным полем в заявке, а через выбранный проект. Эта связь пригодится серверу при проверке полномочий. Схема показывает конкретный учебный набор, а не все возможные записи приложения.',
'Если Анна подаст заявку на другой проект, появится второй объект заявки с другой связью проекта. Анна останется тем же пользователем. Если другой студент выберет проект семнадцать, появится ещё одна заявка с другой связью студента. Такие примеры помогают увидеть, какие объекты общие, а какие создаются для отдельного обращения. Дальше обобщим наблюдение через количество связей.','Начните с центральной заявки, затем пройдите три связи.'),
S('Количество связанных объектов','Один пользователь может иметь много разных заявок',T(['Связь','Количество','Ограничение'],[['Студент — заявки','Один ко многим','У каждой заявки один студент'],['Проект — заявки','Один ко многим','У каждой заявки один проект'],['Преподаватель — проекты','Один ко многим','У проекта один ответственный'],['Студент и проект — заявка','Не более одной для пары','Повтор запрещён']]),
'Количество связанных объектов называют кратностью связи. В нашем примере один студент может иметь много заявок, потому что разрешены разные проекты. У отдельной заявки один студент. Один проект получает много обращений от разных студентов. При этом одна и та же пара студента и проекта встречается не более одного раза. Общее «один ко многим» не отменяет это дополнительное ограничение. Его нужно записать отдельно.',
'Преподаватель может быть связан с несколькими заранее заполненными проектами. У каждого из них в учебной модели один ответственный. Если понадобится совместное руководство, структура изменится: одной ссылки teacher_id окажется недостаточно. Сейчас мы не вводим такую возможность. Кратность помогает увидеть границы выбранной модели и понять, какое новое пожелание потребует пересмотра данных.','Не делайте вывод «одна заявка вообще» из ограничения пары.'),
S('Предметная модель и таблицы','Смысл объектов отличается от способа хранения',T(['Уровень','Пример','Для чего нужен'],[['Предметная модель','Заявка относится к студенту и проекту','Обсудить смысл и правила'],['Табличная модель','applications содержит student_id и project_id','Сохранить связанные записи'],['Интерфейс','Название проекта и статус в списке','Показать человеку результат']]),
'Модель предметной области описывает значимые объекты и связи независимо от конкретного хранилища. Табличная модель уточняет, как их представить строками, столбцами и ограничениями. Интерфейс показывает нужную часть сведений человеку. Эти уровни связаны, но не совпадают полностью. Одна строка списка может собирать название проекта, имя пользователя и состояние заявки из нескольких таблиц. Поэтому копирование всего макета в одну широкую таблицу не является обязательным решением.',
'Для нашего простого случая три основные сущности естественно переходят в три таблицы. Однако объяснение начинается со смысла, а не с названий столбцов. Мы понимаем, почему возникает ссылка и какое правило она поддерживает. Это поможет читать ограничения осмысленно: внешний ключ будет выражать допустимую связь, а уникальная пара — запрет повторной заявки. Дальше посмотрим на поведение объекта.','Не объявляйте любую объектную модель готовой схемой базы.'),
S('Поведение объекта заявки','Изменение состояния следует правилам предметной области',P(['Создание','Назначить pending после допустимой подачи'],['Проверка решения','Проверить преподавателя, проект и исходное состояние'],['Завершение','Сохранить accepted или rejected один раз']),
'Объектную модель можно рассматривать не только как набор полей. У заявки есть допустимое поведение: она создаётся и получает решение по определённым правилам. Произвольная запись нового текста в поле status не описывает смысл рассмотрения. Нужны условия перехода. Ирина должна отвечать за проект, а заявка — находиться в ожидании. Только тогда сохраняется один из итогов. Это связывает данные с действиями, которые уже видели на экранах.',
'Мы не выбираем здесь конкретный стиль программирования или размещение метода в классе. Это проектное описание поведения, которое можно реализовать разными способами. Важнее сохранить правило во всех точках изменения. Даже если обработчик будет устроен иначе, результат не должен допускать решения студентом или повторного пересмотра итогового состояния. Такие проверки станут частью серверного алгоритма.','Не превращайте схему в обязательную реализацию конкретного языка.'),
S('Переход к таблицам','Объекты сохраняются как строки с согласованными полями',T(['Таблица','Что означает одна строка','Основные ссылки'],[['users','Один пользователь','Идентификатор пользователя'],['projects','Один проект','teacher_id указывает пользователя'],['applications','Одна заявка','project_id и student_id']]),
'В реляционной базе данные представляют в таблицах. Одна строка содержит значения одной записи, столбец задаёт вид значения. Для нашего проекта выделим users, projects и applications. Английские названия служат техническими обозначениями, а их смысл уже знаком. В таблице заявок одна строка соответствует одному обращению конкретного студента на конкретный проект. Она не становится отдельной таблицей для каждой новой заявки.',
'Такая структура позволяет получать списки по условиям. Можно выбрать заявки Анны или обращения проекта семнадцать. Имена таблиц не определяют автоматически права доступа: это отдельные правила обработки. Структура также нуждается в ограничениях, чтобы нельзя было случайно сослаться на несуществующий объект или создать повтор. Следующие слайды последовательно введут ключи и затем покажут заполненные учебные строки.','Расшифруйте users, projects и applications по-русски.',[refs.sql]),
S('Первичный ключ','Устойчивое значение отличает одну запись от другой',T(['Таблица','Первичный ключ','Пример'],[['users','id','12 означает Анну'],['projects','id','17 означает выбранный проект'],['applications','id','104 означает конкретную заявку']]),
'Первичный ключ — значение или сочетание значений, которое однозначно отличает строку таблицы. В наших таблицах используем поле id. Для первичного ключа обязательны уникальность и отсутствие пустого значения. Анна имеет номер двенадцать, проект — семнадцать, заявка после создания — сто четыре. Одинаковые числа в разных таблицах не означали бы один объект: значение читают вместе с таблицей. Поэтому одного числа без контекста недостаточно.',
'Имя пользователя не подходит как надёжная замена идентификатору: оно может совпасть у разных людей или измениться. Название проекта тоже может быть исправлено. Устойчивый ключ позволяет сохранить связи при таких изменениях. Здесь мы не утверждаем, что любой ключ обязан быть последовательным числом. Для учебной схемы выбран простой вариант, который удобно прослеживать на экранах и в запросах.','Идентификатор не является секретом или доказательством права.',[refs.constraints]),
S('Внешний ключ','Ссылка должна вести к допустимой существующей записи',D(['users.id','projects.teacher_id','applications.student_id','applications.project_id','projects.id'],[['projects.teacher_id','users.id','Ответственный преподаватель'],['applications.student_id','users.id','Студент заявки'],['applications.project_id','projects.id','Проект заявки']]),
'Внешний ключ связывает значения одной таблицы с ключом другой. В заявке project_id указывает существующий проект, а student_id — существующего пользователя. В проекте teacher_id ссылается на ответственного пользователя. Ограничение базы помогает запретить ссылку на запись, которой нет. Так заявку невозможно согласованно связать с несуществующим проектом. Это защита структуры, а не полная проверка всех бизнес-правил.',
'Обычный внешний ключ на users не доказывает, что роль пользователя student или teacher соответствует смыслу поля. Ролевые правила нужно поддержать отдельно. Также следует определить поведение при удалении связанных объектов. В учебной первой версии операции удаления не рассматриваются. Мы не добавляем автоматическое каскадное уничтожение заявок без отдельного решения, потому что это могло бы разрушить историю обращений.','Отделите существование пользователя от его роли.',[refs.constraints]),
S('Таблица пользователей','Две строки представляют две разные роли',T(['id','full_name','email','role'],[['12','Анна Смирнова','anna@example.test','student'],['7','Ирина Павлова','irina@example.test','teacher']]),
'В таблице users две учебные строки. Каждая содержит собственный ключ, имя, почту и роль. Они участвуют в разных связях. Анна станет student_id заявки, Ирина — teacher_id проекта. Контактные адреса условные и не предназначены для отправки. Мотивация здесь не хранится, потому что один студент может по-разному объяснить интерес к разным проектам. Привязав её к пользователю, мы потеряли бы эту зависимость.',
'На слайде не показаны данные входа. Мы не проектируем отдельный механизм аутентификации в рамках этого примера. Допущение о готовом входе означает, что обработка получает установленного пользователя. Оно не означает, что указанную роль можно свободно прислать из браузера и принять без проверки. Связь с доверенным сеансом подробнее разберём в следующем вебинаре. Сейчас достаточно прочитать значения и их назначение.','Не добавляйте поля пароля в эту учебную таблицу.'),
S('Таблица проектов','Ответственный задан ссылкой, набор — логическим признаком',T(['id','title','teacher_id','is_open'],[['17','Сайт студенческого клуба','7','true']]),
'Строка projects описывает выбранный проект. Для компактности описание не выведено в таблицу целиком, но поле description остаётся в согласованной структуре. Значение teacher_id равно семи и отсылает к Ирине. Признак is_open равен true, поэтому новые заявки возможны при остальных выполненных условиях. Такая строка хранит сведения о проекте один раз. Каждая связанная заявка использует номер семнадцать вместо повторения названия и преподавателя.',
'Если набор закрыли, изменится is_open. Это не требует переписывать каждую заявку на отказ. Если исправили опечатку в названии, связанные представления смогут получить обновлённый текст через тот же ключ. Конечно, в реальном проекте может потребоваться сохранение исторического названия. В нашем учебном договоре такого требования нет, поэтому не добавляем отдельную историю версий без основания.','Уточните, что колонка description скрыта только ради компактности.'),
S('Таблица заявок','Запись появляется после успешной подачи',T(['id','project_id','student_id','status'],[['104','17','12','pending']],'Сокращённое представление: motivation и created_at сохранены, но не выведены в этой таблице.'),
'После создания в applications появляется одна строка. Номер сто четыре обозначает заявку, семнадцать — проект, двенадцать — студента. Статус pending означает ожидание решения. Мотивация и время тоже хранятся, хотя на этой компактной таблице не показаны. Подпись о сокращении важна: отсутствие столбца на иллюстрации не должно создавать впечатление, что поле исчезло из модели. В полном составе сохраняем все согласованные значения.',
'Система назначает номер и время, а пользователя определяет по сеансу. Клиент передаёт выбранный проект и мотивацию. Это распределение уже видно в данных. При повторной подаче с той же парой не должно возникать второй строки даже с другим номером заявки. Первичный ключ защищает идентичность строки, а отдельное ограничение пары защищает правило повтора. Именно это различие сейчас рассмотрим подробнее.','Покажите подпись о сокращённом представлении.'),
S('Типы и обязательность данных','Структура отличает текст, время, признак и ссылку',T(['Поле','Учебное представление','Обязательность'],[['id и ссылки','Целое число','Да'],['motivation','Текст','Да, после нормализации 50–1000'],['is_open','Логический признак','Да'],['status','Одно из трёх значений','Да'],['created_at','Момент времени с часовым поясом','Да']]),
'Тип данных определяет допустимый вид значения. Идентификатор представим целым числом, мотивацию — текстом, состояние набора — логическим признаком, дату — моментом времени. Обязательность означает отсутствие неопределённого значения там, где без него запись теряет смысл. Заявка без студента или проекта не соответствует нашему сценарию. При этом обязательный текст всё равно нуждается в проверке длины. Наличие значения и его допустимость — разные условия.',
'Для времени важно единое правило хранения и отображения. В примерах используем UTC с явным обозначением, а интерфейс может показать локальное представление. Мы не добавляем строковое поле «сегодня», которое завтра изменило бы смысл. Типы и ограничения помогают удержать понятную модель, однако не заменяют проверку прав исполнителя. Следующий слайд покажет ограничение, которое выражает уникальную комбинацию двух обязательных ссылок.','UTC — «ю-ти-си», поясните, что это единая временная основа.'),
S('Уникальность пары','Разные id не разрешают повтор одного обращения',C('SQL','UNIQUE (student_id, project_id)','Оба поля обязательны. Сочетание одного студента и одного проекта встречается не более одного раза.'),
'Первичный ключ id не защищает от двух заявок с разными номерами, но одинаковыми студентом и проектом. Для нашего правила нужно отдельное составное ограничение уникальности. Составное означает, что оно проверяет комбинацию значений. Пара двенадцать и семнадцать может встретиться один раз. Пара двенадцать и другой проект допустима. Так правило точно соответствует исходному договору и не запрещает студенту несколько разных обращений.',
'Оба поля обязательны, чтобы неопределённые значения не обходили смысл ограничения. Интерфейс также может предупреждать о повторе, а сервер — возвращать понятную причину. База удерживает инвариант, то есть правило, которое должно оставаться истинным для сохранённых данных. На третьем занятии увидим, почему эта защита особенно важна при почти одновременных запросах из двух вкладок. Сейчас достаточно правильно прочитать сочетание в скобках.','Не читайте UNIQUE как запрет каждого столбца по отдельности.',[refs.constraints]),
S('Допустимые значения статуса','Хранилище поддерживает согласованный словарь',C('SQL',"CHECK (status IN ('pending', 'accepted', 'rejected'))",'Ограничение набора значений не проверяет самостоятельно право преподавателя и допустимый переход.'),
'Ограничение CHECK проверяет условие для сохраняемой строки. Здесь разрешены только три согласованных значения статуса. Это помогает обнаружить случайную опечатку или неподдерживаемое значение. Однако перечень не задаёт весь жизненный путь. Он не запрещает сам по себе переход из accepted обратно в pending и не проверяет, кто выполняет изменение. Эти правила должны применяться в обработке с учётом текущего состояния и права пользователя.',
'Так мы различаем несколько слоёв защиты согласованности. Тип и обязательность описывают форму значения. Проверка списка ограничивает словарь. Серверная логика связывает изменение с исполнителем и состоянием проекта. Нельзя приписывать короткому фрагменту SQL больше возможностей, чем он выражает. В учебном примере он нужен, чтобы показать конкретное ограничение данных, а не заменить весь алгоритм решения.','CHECK — «чек», IN — принадлежность указанному набору.',[refs.constraints]),
S('Получение связанных данных','Пользовательское представление собирается из нескольких таблиц',T(['Что показываем','Как получаем'],[['Название проекта','applications.project_id связывается с projects.id'],['Имя Анны','applications.student_id связывается с users.id'],['Ответственный преподаватель','projects.teacher_id связывается с users.id'],['Статус и мотивация','Берутся из applications']]),
'Список заявок может показывать больше, чем хранится в одной строке applications. Название проекта получают по связи project_id, имя студента — по student_id. Статус и мотивация относятся к самой заявке. Получение связанных строк в реляционной базе называют соединением. В следующем вебинаре увидим короткий пример SQL. Здесь важно понять источник каждого значения, чтобы не требовать от Анны повторного ввода имени и описания проекта.',
'Сбор представления также должен учитывать права. Возможность технически соединить таблицы не даёт пользователю право получить все строки. Для своих заявок используется условие текущего студента. Для преподавателя — принадлежность проекта. Поэтому структура хранения и логика выдачи дополняют друг друга. На итоговом проходе прототипа проверим, что каждый показанный элемент действительно опирается на известное значение и согласованный доступ.','Объясните соединение обычными словами до упоминания SQL.'),
S('Прототип','Подготовленная модель показывает путь до реализации',P(['Макет','Отдельный вид экрана и его состояния'],['Прототип','Связанная модель переходов для выбранного сценария'],['Реализация','Работающая программа с настоящими обработкой и хранением']),
'Прототип позволяет проверить замысел до полноценной реализации. Он может связывать экраны и демонстрировать реакцию на заранее определённые действия. Это не доказывает, что сервер сохраняет заявку или база защищает повтор. Наши изображения показывают проектное поведение. Поэтому мы называем их макетами и подготовленной последовательностью. Пользовательская убедительность изображения не должна становиться заявлением о выполненной технической проверке.',
'Ценность прототипа состоит в раннем обнаружении смысловых разрывов. Можно заметить, что после ошибки пропал текст, что кнопка обещает немедленное участие или что в списке нет статуса. Такие замечания дешевле исправить до реализации. Затем работающий сервис проверяют отдельно по тем же условиям. Мы завершили проектирование экранов и данных, теперь пройдём два пути целиком, чтобы убедиться в связности решений.','Не представляйте последовательность экранов как запущенный сервис.'),
S('Проход по сценарию Анны','Экран, действие и данные согласованы на каждом шаге',P(['Выбор','Каталог передаёт проект 17 в карточку и форму'],['Ввод','Анна передаёт мотивацию допустимой длины'],['Создание','Система связывает студента 12 и проект 17'],['Просмотр','Заявка 104 видна в своих обращениях со статусом pending']),
'Пройдём путь Анны без остановки на новых определениях. Она выбирает проект, читает условия и открывает форму. Проект уже указан, личность известна по входу. После ввода допустимой мотивации система проверяет условия и создаёт запись. Только после этого интерфейс показывает подтверждение и номер. При возвращении в свои заявки Анна получает ту же запись. Каждый шаг имеет понятное изменение и источник сведений.',
'Теперь проверим связность: форма не требует отсутствующих полей, ответ не обещает одобрение, а список не показывает чужую мотивацию. При ошибке длины текст остаётся, при обрыве подтверждение не выдумывается. Эти дополнения не являются отдельными заданиями аудитории. Это готовый разбор преподавателя, показывающий, как проектные материалы поддерживают полный сценарий, включая важные исключения.','Последовательно укажите четыре шага на подготовленной схеме.'),
S('Проход по сценарию Ирины','Решение относится к заявке собственного проекта',P(['Доступ','Ирина определяется как пользователь 7 с ролью teacher'],['Выбор','Открывает обращения проекта 17, где teacher_id равен 7'],['Рассмотрение','Читает мотивацию заявки 104 в состоянии pending'],['Результат','Сохраняет accepted или rejected, Анна видит тот же итог']),
'Ирина входит в уже действующую систему и открывает собственный проект. Связь teacher_id подтверждает принадлежность. Она читает заявку Анны, которая находится в ожидании. При положительном решении система сохраняет accepted. При отрицательном — rejected. После сохранения обычное повторное рассмотрение недоступно. Анна получает итог через свои заявки, потому что это один объект, а не копия для каждой роли.',
'Если Ирина откроет чужой проект, одной роли teacher будет недостаточно. Если состояние уже итоговое, старая открытая страница не должна разрешить повторное изменение. Эти условия относятся к серверной проверке, но должны быть понятны уже на уровне прототипа. Таким образом, преподавательский путь проверяется и по экрану, и по связям данных. Следующий вебинар покажет, как система применяет эти решения при реальном обмене.','Не вводите дополнительных полномочий преподавателя.'),
S('Связь экранов, требований и данных','Подготовленные представления имеют необходимые источники',T(['Экран и требование','Данные','Проверка согласованности'],[['Подтверждение ФТ-01','applications.id, status','Номер появляется после создания'],['Свой список ФТ-01','student_id текущего пользователя','Чужие заявки не выдаются'],['Решение ФТ-04','project.teacher_id, application.status','Свой проект и исходное pending'],['Форма ПР-02','motivation','Одинаковая граница 50–1000']]),
'Мы получили модель, в которой экранные значения имеют источник, а действия — основание в требованиях. Карточка связана с проектом, форма создаёт заявку, свои списки ограничиваются владельцем, решение опирается на преподавателя и исходное состояние. Если изменить одно правило, по этой таблице можно найти затронутые материалы. Она завершает согласование между пользовательским представлением и хранением. Это подготовленная проверка проекта, а не отчёт об испытании работающего приложения.',
'Теперь у нас есть экраны и структура данных. На следующем занятии разберём, как действие в браузере превращается в запрос, как сервер его обрабатывает и как возникает запись в базе. Будем использовать те же имена полей, номера и статусы. Поэтому технический разбор станет продолжением знакомого пути, а не новым независимым примером.','Завершите готовым переходом к работе приложения.')
];
